sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director (COALESCE(?dbpDeath, ?dboDeath) AS ?deathDate)
WHERE {
  VALUES ?film { dbr:11_Harrowhouse dbr:A_Little_Sister_of_Everybody }

  { ?film dbp:director ?director } UNION { ?film dbo:director ?director }

  OPTIONAL { ?director dbp:deathDate ?dbpDeath }
  OPTIONAL { ?director dbo:deathDate ?dboDeath }
}
LIMIT 100

